const tasks=[
{id:1,name:'Planejamento e projetos',room:'Toda a obra',unit:'etapas',total:5,done:5,weight:5,planned:100,start:0,len:18,team:'Engenharia',dep:'—'},
{id:2,name:'Fundação e estrutura',room:'Toda a obra',unit:'m³',total:40,done:40,weight:25,planned:100,start:14,len:25,team:'Equipe estrutural',dep:'1'},
{id:3,name:'Alvenaria',room:'Toda a obra',unit:'m²',total:200,done:150,weight:20,planned:90,start:34,len:28,team:'Equipe de alvenaria',dep:'2'},
{id:4,name:'Instalações elétricas',room:'Toda a obra',unit:'pontos',total:60,done:24,weight:10,planned:50,start:48,len:23,team:'Equipe elétrica',dep:'3 (por ambiente)'},
{id:5,name:'Instalações hidráulicas',room:'Toda a obra',unit:'pontos',total:30,done:12,weight:10,planned:50,start:48,len:23,team:'Equipe hidráulica',dep:'3 (por ambiente)'},
{id:6,name:'Revestimentos e pisos',room:'Cozinha',unit:'m²',total:30,done:0,weight:15,planned:0,start:67,len:20,team:'Equipe de acabamento',dep:'4 e 5'},
{id:7,name:'Pintura e acabamentos',room:'Toda a obra',unit:'m²',total:350,done:0,weight:10,planned:0,start:82,len:15,team:'Equipe de acabamento',dep:'6'},
{id:8,name:'Vistoria e entrega',room:'Toda a obra',unit:'etapas',total:4,done:0,weight:5,planned:0,start:96,len:4,team:'Engenharia',dep:'7'}];
const rooms=[{name:'Quarto 01',x:30,y:30,w:165,h:140,alv:100,ele:60},{name:'Quarto 02',x:200,y:30,w:165,h:140,alv:80,ele:30},{name:'Banheiro',x:370,y:30,w:120,h:140,alv:70,ele:35},{name:'Sala de estar',x:30,y:175,w:270,h:180,alv:75,ele:40},{name:'Cozinha',x:305,y:175,w:185,h:180,alv:50,ele:20}];
const pages=[['painel','◫','Visão geral','Visão geral da obra','Tudo o que você precisa acompanhar, em um só lugar.'],['cronograma','▤','Cronograma','Cronograma da obra','Etapas conectadas, do planejamento à entrega.'],['semana','▦','Planejamento semanal','Planejamento semanal','Organize as frentes de trabalho e os recursos da semana.'],['planta','⌑','Planta e avanço','A obra, ambiente por ambiente','Selecione uma etapa para acompanhar sua execução na planta.'],['diario','▧','Diário de obra','Diário de obra','Transforme a execução do canteiro em informação para o planejamento.']];
let entries=[],selectedRoom=0,layer='alv';
const $=s=>document.querySelector(s);const pct=t=>t.done/t.total*100;const actual=()=>tasks.reduce((a,t)=>a+pct(t)*t.weight/100,0);const planned=()=>tasks.reduce((a,t)=>a+t.planned*t.weight/100,0);const fmt=n=>n.toLocaleString('pt-BR',{maximumFractionDigits:1});const progress=n=>`<div class="track"><i style="width:${n}%"></i></div>`;
function escapeText(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function chart(){let a=actual();return `<svg class="chart" viewBox="0 0 600 255" role="img" aria-label="Curva S: planejado ${fmt(planned())} por cento; realizado ${fmt(a)} por cento. Histórico anterior ilustrativo."><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#4d9980" stop-opacity=".15"/><stop offset="1" stop-color="#4d9980" stop-opacity="0"/></linearGradient></defs>${[0,25,50,75,100].map(n=>`<line class="axis" x1="40" y1="${220-n*1.9}" x2="575" y2="${220-n*1.9}"/><text x="2" y="${225-n*1.9}">${n}%</text>`).join('')}<path d="M40 220 L120 201 L200 155 L275 ${220-a*1.9} L275 220Z" fill="url(#fill)"/><path class="planned-line" d="M40 220 L120 200 L200 147 L275 ${220-planned()*1.9} L380 65 L475 36 L575 30"/><path class="actual-line" d="M40 220 L120 201 L200 155 L275 ${220-a*1.9}"/><line x1="275" y1="20" x2="275" y2="220" stroke="#bac9cf" stroke-dasharray="3 4"/><circle cx="275" cy="${220-a*1.9}" r="5" fill="#378b73"/>${['Ago','Set','Out','Nov','Dez'].map((v,i)=>`<text x="${40+i*132}" y="247">${v}</text>`).join('')}<text x="283" y="20">02 out</text></svg>`}
function plan(){return `<div class="plan"><svg viewBox="0 0 520 390" role="group" aria-label="Planta ilustrativa de uma casa. Selecione um ambiente.">${rooms.map((r,i)=>{let n=layer==='alv'?r.alv:layer==='ele'?r.ele:(i===4?pct(tasks[5]):0);return `<g><rect class="room" role="button" tabindex="0" aria-label="${r.name}: ${fmt(n)}% concluído" data-room="${i}" x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" fill="${n>=100?'#91bba6':n>0?'#e7ce9a':'#e2e8eb'}"/><text x="${r.x+r.w/2}" y="${r.y+r.h/2-6}" text-anchor="middle">${r.name}</text><text class="percent" x="${r.x+r.w/2}" y="${r.y+r.h/2+16}" text-anchor="middle">${fmt(n)}% concluído</text></g>`}).join('')}<path class="plan-wall" d="M30 30H490V355H30Z M197 30V170 M367 30V170 M30 172H490 M302 175V355"/><text x="260" y="382" text-anchor="middle" style="font-size:11px;fill:#8699a1">PLANTA ILUSTRATIVA · SEM ESCALA</text></svg></div>`}
function bindRooms(){document.querySelectorAll('[data-room]').forEach(el=>{const go=()=>{selectedRoom=Number(el.dataset.room);location.hash='planta';render()};el.onclick=go;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}}})}
function dashboard(){return `<div class="cards"><div class="card"><div class="card-label">Avanço físico realizado</div><div class="metric">${fmt(actual())}<small> %</small></div>${progress(actual())}<div class="muted">Planejado para hoje: ${fmt(planned())}%</div></div><div class="card"><div class="card-label">Desvio do planejamento</div><div class="metric warning">${fmt(actual()-planned())}<small> p.p.</small></div><div class="muted">Diferença entre realizado e planejado</div></div><div class="card"><div class="card-label">Etapas concluídas</div><div class="metric">${tasks.filter(t=>pct(t)===100).length}<small> / ${tasks.length}</small></div><div class="muted">${tasks.filter(t=>pct(t)>0&&pct(t)<100).length} etapas em execução</div></div><div class="card"><div class="card-label">Prazo até a entrega</div><div class="metric">77<small> dias</small></div><div class="muted">Referência: 02 de outubro de 2026</div></div></div><div class="grid"><section class="panel"><div class="panel-head"><h2>Curva S · avanço da obra</h2><div class="legend"><span class="planned">Planejado</span><span>Realizado</span></div></div>${chart()}<p class="muted">Avanço ponderado por etapa. Histórico e projeção ilustrativos; valor atual calculado pelos apontamentos.</p></section><section class="panel"><div class="panel-head"><h2>Execução na planta</h2><a class="text-link" href="#planta">Ver ambientes</a></div>${plan()}<div class="legend" style="margin-top:15px"><span>Concluído</span><span class="running">Em execução</span><span class="pending">Pendente</span></div></section></div><section class="panel"><div class="panel-head"><h2>Frentes em andamento</h2><a class="text-link" href="#semana">Planejar a semana</a></div>${tasks.filter(t=>pct(t)>0&&pct(t)<100).map(t=>`<div class="task-row"><div><h3>${t.name}</h3><small>${t.team} · ${fmt(t.done)} de ${t.total} ${t.unit}</small></div><div>${fmt(pct(t))}% ${progress(pct(t))}</div></div>`).join('')}</section>`}
function schedule(){return `<div class="notice">Alvenaria está abaixo do previsto. Dependências e datas são demonstrativas; o recálculo automático do cronograma será desenvolvido na versão piloto.</div><section class="panel"><div class="panel-head"><h2>Etapas da construção</h2><div class="legend"><span>Executado</span><span class="pending">Restante</span></div></div><div class="table-wrap"><table class="gantt"><thead><tr><th>Atividade / dependência</th><th>Avanço</th><th>Peso</th><th>Ago &emsp;&emsp; Set &emsp;&emsp; Out &emsp;&emsp; Nov &emsp;&emsp; Dez</th></tr></thead><tbody>${tasks.map(t=>`<tr><td><strong>${t.id}. ${t.name}</strong><div class="dependency">Depende de: ${t.dep}</div></td><td>${fmt(pct(t))}%</td><td>${t.weight}%</td><td class="timeline"><div class="bar" title="${t.name}" style="margin-left:${t.start}%;width:${t.len}%"><i style="width:${pct(t)}%"></i></div></td></tr>`).join('')}</tbody></table></div></section><div class="grid" style="margin-top:24px"><section class="panel"><h2>Como o avanço é medido</h2><p style="margin-top:12px">Quantidade executada ÷ quantidade prevista. Cada etapa contribui para o avanço geral conforme seu peso no planejamento.</p></section><section class="panel"><h2>Calendário da obra</h2><div class="task-row"><span>Jornada</span><strong>Segunda a sexta</strong></div><div class="task-row"><span>Entrega prevista</span><strong>18 dez 2026</strong></div></section></div>`}
function weekly(){const jobs=[['Alvenaria · Quarto 02','Equipe de alvenaria · 3 pessoas','Blocos: 180 un.'],['Alvenaria · Banheiro','Equipe de alvenaria · 3 pessoas','Argamassa: 6 sacos'],['Elétrica · Sala','Equipe elétrica · 2 pessoas','Eletrodutos: 24 m'],['Hidráulica · Cozinha','Equipe hidráulica · 2 pessoas','Tubos: 18 m'],['Alvenaria · Cozinha','Equipe de alvenaria · 3 pessoas','Blocos: 220 un.']];return `<section class="panel"><div class="panel-head"><h2>28 setembro — 02 outubro 2026</h2><span class="pill">Semana 40</span></div><div class="week">${jobs.map((j,i)=>`<div class="day ${i===4?'today':''}"><div class="day-head">${['Segunda','Terça','Quarta','Quinta','Sexta'][i]}<strong>${[28,29,30,'01','02'][i]}</strong></div><div class="job"><h3>${j[0]}</h3><small>${j[1]}</small><div>${j[2]}</div><small>Betoneira ${i<2||i===4?'01':'não necessária'}</small><button data-record="${i===2?4:i===3?5:3}">Apontar execução</button></div></div>`).join('')}</div></section><h2 style="margin:25px 0 15px">Recursos da semana</h2><div class="resource-grid"><section class="panel"><h3>Mão de obra</h3><div class="task-row"><span>Alvenaria</span><strong>3 / 3</strong></div><div class="task-row"><span>Elétrica</span><strong>2 / 2</strong></div><div class="task-row"><span>Hidráulica</span><strong>2 / 2</strong></div><small>Pessoas alocadas / disponíveis</small></section><section class="panel"><h3>Equipamentos</h3><div class="task-row"><span>Betoneira 01</span><span class="pill">Alocada</span></div><div class="task-row"><span>Andaime 01</span><span class="pill">Disponível</span></div><small>Alocação demonstrativa, sem conflitos nesta semana.</small></section><section class="panel"><h3>Materiais</h3><div class="task-row"><span>Blocos</span><strong>400 / 500 un.</strong></div><div class="task-row"><span>Argamassa</span><strong>6 / 20 sacos</strong></div><div class="task-row"><span>Eletrodutos</span><strong>24 / 40 m</strong></div><small>Necessário na semana / disponível</small></section></div>`}
function plantPage(){let r=rooms[selectedRoom],n=layer==='alv'?r.alv:layer==='ele'?r.ele:(selectedRoom===4?pct(tasks[5]):0);return `<div class="toolbar"><label for="layer">Etapa da construção</label><select id="layer"><option value="alv">Alvenaria</option><option value="ele">Instalações elétricas</option><option value="piso">Revestimentos e pisos</option></select></div><div class="grid"><section class="panel"><div class="panel-head"><h2>Pavimento térreo</h2><div class="legend"><span>Concluído</span><span class="running">Em execução</span><span class="pending">Pendente</span></div></div>${plan()}<p class="muted" style="margin-top:15px">Selecione um ambiente para consultar o andamento.</p></section><section class="panel"><h2>${r.name}</h2><div class="details"><p>${layer==='alv'?'Alvenaria':layer==='ele'?'Instalações elétricas':'Revestimentos e pisos'}</p><strong>${fmt(n)}% concluído</strong>${progress(n)}<small>${n===100?'Etapa concluída':n>0?'Execução em andamento':'Execução ainda não iniciada'}</small></div>${rooms.map((r,i)=>`<div class="room-summary"><button data-select-room="${i}">${r.name}</button><span>${fmt(layer==='alv'?r.alv:layer==='ele'?r.ele:i===4?pct(tasks[5]):0)}%</span></div>`).join('')}<p style="margin-top:20px">Esta planta é um exemplo. A importação de PDF e a marcação de áreas serão implementadas na versão piloto; arquivos AutoCAD entrarão em uma etapa posterior.</p></section></div>`}
function diary(){return `<div class="grid"><section class="panel"><div class="panel-head"><h2>Novo registro de execução</h2><span class="pill">02 out 2026</span></div><form id="entry-form"><div class="form-grid"><div class="field wide"><label for="task">Atividade</label><select id="task" name="task">${tasks.map(t=>`<option value="${t.id}">${t.name} · ${t.room}</option>`).join('')}</select></div><div class="field"><label for="room">Ambiente</label><select id="room" name="room"><option>Toda a obra</option>${rooms.map(r=>`<option>${r.name}</option>`).join('')}</select></div><div class="field"><label for="date">Data</label><input id="date" name="date" type="date" value="2026-10-02" required max="2026-10-02" min="2026-08-03"></div><div class="field wide"><label for="quantity" id="quantity-label">Quantidade executada neste registro</label><input id="quantity" name="quantity" type="number" min="0.01" step="0.01" required placeholder="Ex.: 15"><small id="remaining"></small></div><div class="field wide"><label for="note">Observações</label><textarea id="note" name="note" rows="3" maxlength="1000" placeholder="Descreva o trabalho executado e eventuais impedimentos."></textarea></div></div><div class="form-actions"><button class="primary" type="submit">Salvar execução</button></div></form><p class="muted" style="margin-top:15px">O registro atualiza os indicadores nesta sessão. Fotos e sincronização serão incluídas na versão piloto.</p></section><section class="panel"><div class="panel-head"><h2>Registros da obra</h2><span class="muted">${entries.length} nesta sessão</span></div>${entries.length?entries.slice().reverse().map(e=>`<div class="entry"><small>${escapeText(e.date.split('-').reverse().join('/'))} · ${escapeText(e.room)}</small><h3>${escapeText(e.task)}</h3><span class="pill">＋ ${fmt(e.qty)} ${e.unit}</span><p style="margin-top:9px">${escapeText(e.note||'Sem observações.')}</p></div>`).join(''):'<div class="empty">Nenhum registro nesta sessão.<br>Faça um apontamento para ver a obra avançar.</div>'}</section></div>`}
function record(id,qty,room,date,note){const t=tasks.find(t=>t.id===Number(id));if(!t||!Number.isFinite(qty)||qty<=0||qty>t.total-t.done+1e-8)throw Error('Informe uma quantidade maior que zero e até o saldo restante da atividade.');if(!['Toda a obra',...rooms.map(r=>r.name)].includes(room))throw Error('Selecione um ambiente válido.');if(t.id===6&&room!=='Cozinha')throw Error('Esta atividade de pisos está vinculada à Cozinha.');if(!/^2026-\d{2}-\d{2}$/.test(date)||date<'2026-08-03'||date>'2026-10-02'||Number.isNaN(Date.parse(date)))throw Error('Selecione uma data entre o início da obra e 02/10/2026.');t.done=Math.min(t.total,t.done+qty);if(t.id===3||t.id===4){let key=t.id===3?'alv':'ele';if(room==='Toda a obra')rooms.forEach(r=>r[key]=pct(t));else {const r=rooms.find(r=>r.name===room);r[key]=Math.min(100,r[key]+qty/t.total*100)}}entries.push({task:t.name,qty,unit:t.unit,room,date,note});render();toast('Execução registrada. O avanço da obra foi atualizado.');return {advance:actual(),taskAdvance:pct(t)}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4200)}
function render(){let key=location.hash.slice(1)||'painel',p=pages.find(p=>p[0]===key)||pages[0];$('nav').innerHTML=pages.map(v=>`<a href="#${v[0]}" class="${v[0]===p[0]?'active':''}" ${v[0]===p[0]?'aria-current="page"':''}><span>${v[1]}</span>${v[2]}</a>`).join('');$('#title').textContent=p[3];$('#subtitle').textContent=p[4];$('#content').innerHTML=({painel:dashboard,cronograma:schedule,semana:weekly,planta:plantPage,diario:diary})[p[0]]();bindRooms();if($('#layer')){$('#layer').value=layer;$('#layer').onchange=e=>{layer=e.target.value;render()}}document.querySelectorAll('[data-select-room]').forEach(b=>b.onclick=()=>{selectedRoom=Number(b.dataset.selectRoom);render()});document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>{location.hash='diario';setTimeout(()=>{$('#task').value=b.dataset.record;updateForm()},0)});if($('#entry-form')){$('#task').value=6;updateForm();$('#task').onchange=updateForm;$('#entry-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);try{record(f.get('task'),Number(f.get('quantity')),f.get('room'),f.get('date'),f.get('note'))}catch(err){toast(err.message)}}}}
function updateForm(){let t=tasks.find(t=>t.id===Number($('#task').value));$('#quantity-label').textContent=`Quantidade executada neste registro (${t.unit})`;$('#remaining').textContent=`Executado: ${fmt(t.done)} de ${t.total} ${t.unit} · Restante: ${fmt(t.total-t.done)} ${t.unit}`;$('#quantity').max=t.total-t.done;$('#room').value=t.room;$('#room').disabled=t.id===6;if(t.id===6){$('#room').disabled=false;$('#room').onchange=()=>{$('#room').value='Cozinha'}}else $('#room').onchange=null;}
$('#new-entry').onclick=()=>{location.hash='diario';if($('#quantity'))$('#quantity').focus()};window.addEventListener('hashchange',render);render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_construction_progress',description:'Consulta os indicadores e etapas da obra demonstrativa na sessão atual.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({actual:actual(),planned:planned(),tasks:tasks.map(t=>({id:t.id,name:t.name,done:t.done,total:t.total,unit:t.unit}))})})).catch(()=>{});}catch{}}
